def verify(witness):
    if type(witness) is not dict:
        raise ValueError('witness must be a dict')
    if set(witness.keys()) != {'N', 'permutation'}:
        raise ValueError('witness keys must be exactly N and permutation')
    N = witness['N']
    perm = witness['permutation']
    if type(N) is not int:
        raise ValueError('N must be an int')
    if N < 1:
        raise ValueError('N must be positive')
    if type(perm) is not list:
        raise ValueError('permutation must be a list')
    if len(perm) != N:
        raise ValueError('permutation length mismatch')
    for v in perm:
        if type(v) is not int:
            raise ValueError('values must be ints')
    if sorted(perm) != list(range(1, N + 1)):
        raise ValueError('not a permutation of [N]')
    for i in range(N):
        for j in range(i + 1, N):
            for k in range(j + 1, N):
                for l in range(k + 1, N):
                    d = perm[j] - perm[i]
                    if d != 0 and perm[k] - perm[j] == d and perm[l] - perm[k] == d:
                        raise ValueError('monotone 4-term AP at indices %d,%d,%d,%d' % (i, j, k, l))
    return True
